import{_ as s,C as r,o as i,c as l,j as t,a,E as n,ag as d}from"./chunks/framework.DMVuHR7L.js";const w=JSON.parse('{"title":"Appearance & settings","description":"","frontmatter":{},"headers":[],"relativePath":"features/settings.md","filePath":"features/settings.md","lastUpdated":1779922360000}'),p={name:"features/settings.md"};function c(h,e,g,u,m,f){const o=r("ThemeImage");return i(),l("div",null,[e[0]||(e[0]=t("h1",{id:"appearance-settings",tabindex:"-1"},[a("Appearance & settings "),t("a",{class:"header-anchor",href:"#appearance-settings","aria-label":'Permalink to "Appearance & settings"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("WebLogcat's chrome is intentionally small — most state belongs to individual widgets. Two places carry global preferences: the "),t("strong",null,"appearance"),a(" popover and the "),t("strong",null,"global settings"),a(" modal.")],-1)),n(o,{"src-dark":"/img/features/topbar.png","src-light":"/img/features/topbar-light.png",alt:"Topbar"}),e[2]||(e[2]=d('<h2 id="appearance-popover" tabindex="-1">Appearance popover <a class="header-anchor" href="#appearance-popover" aria-label="Permalink to &quot;Appearance popover&quot;">​</a></h2><p>The half-circle icon in the topbar opens an appearance popover with three controls:</p><ul><li><strong>Theme.</strong> Light / Dark. Both are first-class — the design tokens are hand-tuned for both modes.</li><li><strong>Color scheme.</strong> Indigo, Teal, Amber, or Rose. Picks the accent hue that flows through buttons, focus rings, level pills, etc. — driven by <code>--accent-hue</code> in <code>tokens.css</code>.</li><li><strong>Layout: Compact mode.</strong> Drops the gap and the rounded corners between tiles so widgets share every pixel of the dashboard. Useful on smaller laptops.</li></ul><p>Preferences persist via <code>localStorage</code> and apply instantly — no reload.</p><h2 id="global-settings-modal" tabindex="-1">Global settings modal <a class="header-anchor" href="#global-settings-modal" aria-label="Permalink to &quot;Global settings modal&quot;">​</a></h2><p>The cog icon in the topbar opens a modal with cross-cutting options:</p><ul><li><strong>Performance mode.</strong> Disables the position transition on tiles and reduces a few non-essential animations. Auto-on if the OS reports <code>prefers-reduced-motion: reduce</code>. Pin to <em>On</em> if your laptop struggles with the dashboard at 120 Hz.</li><li><strong>Simulated stream speed.</strong> Affects only the <a href="./simulator">simulator</a>. Trickle / Steady / Firehose; defaults to Steady.</li><li><strong>Reset all preferences.</strong> Wipes every <code>weblogcat:*</code> <code>localStorage</code> key and reloads.</li></ul><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><p>Each widget exposes its own settings modal via the cog in its tile header. The contents are widget-specific — see the relevant feature page:</p><ul><li><a href="./logcat#per-widget-settings">Logcat</a></li><li><a href="./shell#per-widget-settings">Shell</a></li><li><a href="./dumpsys#per-widget-settings">Dumpsys</a></li><li><a href="./files#per-widget-settings">Files</a></li><li><a href="./screen-mirror#per-widget-settings">Screen Mirror</a></li></ul><h2 id="widget-palette" tabindex="-1">Widget palette <a class="header-anchor" href="#widget-palette" aria-label="Permalink to &quot;Widget palette&quot;">​</a></h2><p><code>+ Add widget</code> in the topbar opens the palette. Five cards, one per kind; disabled cards (e.g. Mirror after one is already mounted) are greyed out with the reason on hover.</p><p>The palette also supports the keyboard:</p><ul><li><code>↑</code> / <code>↓</code> to move the selection.</li><li><code>Enter</code> to add the highlighted widget.</li><li><code>Esc</code> to dismiss.</li></ul><h2 id="help-dialog" tabindex="-1">Help dialog <a class="header-anchor" href="#help-dialog" aria-label="Permalink to &quot;Help dialog&quot;">​</a></h2><p><code>?</code> anywhere in the app opens the <strong>Keyboard shortcuts</strong> dialog. It&#39;s the authoritative list — the tables in this site are kept in sync but the dialog is what ships in the build.</p>',16))])}const v=s(p,[["render",c]]);export{w as __pageData,v as default};
